// Command evsbench converts real JSONL evidence to the canonical binary stream
// and compares query performance on both.
//
// Every analytics figure for the binary format so far came from a synthetic
// corpus generated by the same code that reads it, which is the weakest form of
// evidence available. This runs the comparison on evidence a real simulation
// actually wrote: the same bytes the production analyzer consumes, with the
// same field shapes, string cardinality and record ordering.
//
//	evsbench -in <venue>/spot/ABC-USD.jsonl -event BookDelta
package main

import (
	"bufio"
	"encoding/json"
	"flag"
	"fmt"
	"log"
	"os"
	"time"

	"exchange_sim/evstream"
	"exchange_sim/evstream/exsim"
)

// jsonlRecord is the persisted envelope: a venue wrapper around the payload the
// exchange logged.
type jsonlRecord struct {
	ClientID uint64 `json:"client_id"`
	Event    string `json:"event"`
	SimTS    int64  `json:"sim_ts"`
	Data     struct {
		VenueID string `json:"venue_id"`
		Payload struct {
			HiddenQty  int64  `json:"hidden_qty"`
			Price      int64  `json:"price"`
			Side       string `json:"side"`
			TotalQty   int64  `json:"total_qty"`
			VisibleQty int64  `json:"visible_qty"`
		} `json:"payload"`
	} `json:"data"`
}

func main() {
	in := flag.String("in", "", "JSONL evidence file to read")
	eventName := flag.String("event", "BookDelta", "event family to extract")
	symbol := flag.String("symbol", "ABC/USD", "symbol these records belong to")
	limit := flag.Int("limit", 0, "stop after this many matching records; 0 reads all")
	flag.Parse()
	if *in == "" {
		log.Fatal("evsbench: -in is required")
	}

	events, jsonlBytes, scanned := readEvents(*in, *eventName, *symbol, *limit)
	if len(events) == 0 {
		log.Fatalf("evsbench: no %s records found in %s", *eventName, *in)
	}
	fmt.Printf("source          %s\n", *in)
	fmt.Printf("records         %d matching %s, from %d lines\n", len(events), *eventName, scanned)
	fmt.Printf("jsonl bytes     %d (%.1f per record)\n", jsonlBytes, float64(jsonlBytes)/float64(len(events)))

	stream, index, dict, encodeElapsed := encode(events)
	fmt.Printf("binary bytes    %d (%.1f per record, %.2fx smaller)\n",
		len(stream), float64(len(stream))/float64(len(events)),
		float64(jsonlBytes)/float64(len(stream)))
	fmt.Printf("encode          %v (%.0f ns/record)\n", encodeElapsed.Round(time.Millisecond),
		float64(encodeElapsed.Nanoseconds())/float64(len(events)))
	fmt.Printf("blocks          %d\n\n", len(index.Blocks))

	// The queries are deliberately the two shapes that behave differently: a
	// narrow time window, where a block index can skip almost everything, and a
	// whole-run aggregate, where it cannot skip anything at all.
	firstTS, lastTS := events[0].Timestamp, events[len(events)-1].Timestamp
	span := lastTS - firstTS
	windowStart := firstTS + span/2
	windowEnd := windowStart + span/100

	fmt.Printf("%-34s %12s %12s %10s\n", "query", "jsonl", "binary", "speedup")
	runQuery("A  1%% time window, one side", *in, *eventName,
		func(r *jsonlRecord) bool {
			return r.SimTS >= windowStart && r.SimTS <= windowEnd && r.Data.Payload.Side == "BUY"
		},
		stream, index, dict,
		evstream.Query{FromTS: windowStart, ToTS: windowEnd, Families: []uint16{exsim.SchemaBookDelta}},
		func(d *exsim.BookDelta) bool { return d.Side == 0 })

	runQuery("B  whole-run aggregate", *in, *eventName,
		func(r *jsonlRecord) bool { return true },
		stream, index, dict,
		evstream.Query{Families: []uint16{exsim.SchemaBookDelta}},
		func(d *exsim.BookDelta) bool { return true })
}

func readEvents(path, eventName, symbol string, limit int) ([]exsim.BookDelta, int64, int) {
	file, err := os.Open(path)
	if err != nil {
		log.Fatalf("evsbench: open: %v", err)
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	scanner.Buffer(make([]byte, 0, 1<<20), 1<<22)
	var (
		events     []exsim.BookDelta
		jsonlBytes int64
		scanned    int
	)
	needle := []byte(`"event":"` + eventName + `"`)
	for scanner.Scan() {
		scanned++
		line := scanner.Bytes()
		if !containsBytes(line, needle) {
			continue
		}
		var record jsonlRecord
		if err := json.Unmarshal(line, &record); err != nil {
			continue
		}
		if record.Event != eventName {
			continue
		}
		side := uint8(0)
		if record.Data.Payload.Side == "SELL" {
			side = 1
		}
		events = append(events, exsim.BookDelta{
			Timestamp: record.SimTS, Symbol: symbol, Side: side,
			Price:      record.Data.Payload.Price,
			VisibleQty: record.Data.Payload.VisibleQty,
			HiddenQty:  record.Data.Payload.HiddenQty,
			TotalQty:   record.Data.Payload.TotalQty,
		})
		jsonlBytes += int64(len(line)) + 1
		if limit > 0 && len(events) >= limit {
			break
		}
	}
	return events, jsonlBytes, scanned
}

func containsBytes(haystack, needle []byte) bool {
	if len(needle) > len(haystack) {
		return false
	}
	for i := 0; i+len(needle) <= len(haystack); i++ {
		if haystack[i] == needle[0] && string(haystack[i:i+len(needle)]) == string(needle) {
			return true
		}
	}
	return false
}

func encode(events []exsim.BookDelta) ([]byte, *evstream.Index, *evstream.Dictionary, time.Duration) {
	buffer := &growBuffer{}
	started := time.Now()
	writer := evstream.NewWriter(buffer, evstream.WriterOptions{})
	var encoded exsim.EncodedBookDelta
	for i := range events {
		if err := exsim.InternBookDelta(writer, events[i], &encoded); err != nil {
			log.Fatalf("evsbench: intern: %v", err)
		}
		ref, _ := writer.Dictionary().Lookup(events[i].Symbol)
		if err := writer.Append(events[i].Timestamp, 0, ref, &encoded); err != nil {
			log.Fatalf("evsbench: append: %v", err)
		}
	}
	if err := writer.Flush(); err != nil {
		log.Fatalf("evsbench: flush: %v", err)
	}
	return buffer.bytes, writer.Index(), writer.Dictionary(), time.Since(started)
}

type growBuffer struct{ bytes []byte }

func (g *growBuffer) Write(p []byte) (int, error) {
	g.bytes = append(g.bytes, p...)
	return len(p), nil
}

func runQuery(name, path, eventName string, keepJSON func(*jsonlRecord) bool,
	stream []byte, index *evstream.Index, dict *evstream.Dictionary,
	query evstream.Query, keepBinary func(*exsim.BookDelta) bool) {

	jsonElapsed, jsonMatched := timeJSONScan(path, eventName, keepJSON)
	binaryElapsed, binaryMatched := timeBinaryScan(stream, index, dict, query, keepBinary)

	agreement := "ok"
	if jsonMatched != binaryMatched {
		// Reported rather than hidden: a faster scan that answers a different
		// question is not a faster scan.
		agreement = fmt.Sprintf("MISMATCH json=%d binary=%d", jsonMatched, binaryMatched)
	}
	fmt.Printf("%-34s %12v %12v %9.1fx  matched %d %s\n", name,
		jsonElapsed.Round(time.Millisecond), binaryElapsed.Round(time.Microsecond),
		float64(jsonElapsed)/float64(binaryElapsed), jsonMatched, agreement)
}

func timeJSONScan(path, eventName string, keep func(*jsonlRecord) bool) (time.Duration, int) {
	file, err := os.Open(path)
	if err != nil {
		log.Fatalf("evsbench: reopen: %v", err)
	}
	defer file.Close()
	started := time.Now()
	scanner := bufio.NewScanner(file)
	scanner.Buffer(make([]byte, 0, 1<<20), 1<<22)
	matched := 0
	needle := []byte(`"event":"` + eventName + `"`)
	for scanner.Scan() {
		line := scanner.Bytes()
		if !containsBytes(line, needle) {
			continue
		}
		var record jsonlRecord
		if err := json.Unmarshal(line, &record); err != nil {
			continue
		}
		if record.Event == eventName && keep(&record) {
			matched++
		}
	}
	return time.Since(started), matched
}

func timeBinaryScan(stream []byte, index *evstream.Index, dict *evstream.Dictionary,
	query evstream.Query, keep func(*exsim.BookDelta) bool) (time.Duration, int) {
	started := time.Now()
	blocks, _ := index.Select(query)
	reader := evstream.NewIndexedReader(newByteReaderAt(stream), evstream.CodecNone, dict, nil)
	matched := 0
	var into exsim.BookDelta
	if err := reader.RangeSelected(blocks, query, func(frame evstream.Frame) error {
		if err := exsim.DecodeBookDelta(frame, dictResolver{dict}, &into); err != nil {
			return err
		}
		if keep(&into) {
			matched++
		}
		return nil
	}); err != nil {
		log.Fatalf("evsbench: scan: %v", err)
	}
	return time.Since(started), matched
}

// dictResolver adapts the dictionary's id-to-string direction to the schema's
// Resolver interface. The dictionary exposes both directions under different
// names because interning and resolving are different operations.
type dictResolver struct{ dict *evstream.Dictionary }

func (d dictResolver) Lookup(id uint32) (string, bool) { return d.dict.Value(id) }

type byteReaderAt struct{ data []byte }

func newByteReaderAt(data []byte) *byteReaderAt { return &byteReaderAt{data: data} }

func (b *byteReaderAt) ReadAt(p []byte, off int64) (int, error) {
	if off >= int64(len(b.data)) {
		return 0, fmt.Errorf("offset %d beyond %d", off, len(b.data))
	}
	return copy(p, b.data[off:]), nil
}
